'use strict';

function f1() {
  const parts = [];
  for (let i = 0; i < 8; i++) {
    parts.push(String(i * 7 + 3));
    parts.push('padding-to-make-this-body-measurably-large-' + i);
  }
  const joined = parts.filter((p) => p.length > 0).join('|');
  return 'f1:' + joined.length + ':' + parts.length;
}

function f2() {
  const acc = { total: 0, items: [] };
  for (let i = 0; i < 12; i++) {
    acc.total += i * i;
    acc.items.push('second-implementation-padding-block-' + i);
  }
  const digest = acc.items.map((s) => s.slice(-6)).join(',');
  return 'f2:' + acc.total + ':' + digest.length;
}

exports.x = f1;
exports.fromCycle = require('./b.js').early;
exports.x = f2;
exports.legacy = f1;
